// Format for Insert — unpacks embedding batches, builds INSERT queries.
// Emits a DELETE for each file before its first INSERT to allow clean re-ingestion.

const items = $input.all();
const chunkBatches = $('Preparing Chunks').all();
const out = [];

// Dollar-quoting: SQL-injection-proof escaping for PostgreSQL.
function dollarQuote(s) {
  let tag = 'q';
  while (s.includes('$' + tag + '$')) tag += '_';
  return '$' + tag + '$' + s + '$' + tag + '$';
}

// L2-normalize. gemini-embedding-001 only returns pre-normalized
// vectors at 3072 dims; at 1536 you must normalize yourself.
function l2normalize(v) {
  let norm = 0;
  for (const x of v) norm += x * x;
  norm = Math.sqrt(norm);
  return norm > 0 ? v.map(x => x / norm) : v;
}

const SQ = "'";
const deletedFiles = new Set();

for (let i = 0; i < items.length; i++) {
  const embeddings = items[i].json.embeddings;
  if (!embeddings || !Array.isArray(embeddings)) {
    const errMsg = items[i].json.error?.message || JSON.stringify(items[i].json).slice(0, 500);
    throw new Error('Embedding API error for batch ' + i + ': ' + errMsg);
  }
  const chunks = chunkBatches[i].json.chunks;

  for (let j = 0; j < embeddings.length; j++) {
    const embedding = l2normalize(embeddings[j].values);
    const chunk = chunks[j];

    // Delete all existing rows for this file before the first insert.
    // Keyed on file_id, not the file name: file_id is stable across Drive
    // renames, so a renamed file replaces its old rows instead of orphaning
    // them under the old name -- the sync's orphan sweep would not catch
    // those, because the file_id is still present in Drive.
    const fileKey = chunk.file_id;
    if (fileKey && !deletedFiles.has(fileKey)) {
      deletedFiles.add(fileKey);
      out.push({
        json: {
          query: "DELETE FROM documents WHERE metadata->>'file_id' = " + dollarQuote(fileKey)
        }
      });
    }

    const metadata = JSON.stringify({
      file_id: chunk.file_id,
      original_file_name: chunk.original_file_name,
      section_heading: chunk.section_heading,
      chunk_index: chunk.chunk_index,
      // Both ingestion branches share this table. The sync's orphan sweep is
      // scoped to source='knowledge_base' so it cannot delete expert feedback.
      source: 'knowledge_base'
    });
    const embeddingStr = '[' + embedding.join(',') + ']';
    const lastModifiedSql = chunk.last_modified
      ? dollarQuote(chunk.last_modified) + '::timestamptz'
      : 'NULL';
    out.push({
      json: {
        query: 'INSERT INTO documents (content, metadata, embedding, last_modified) VALUES (' +
          dollarQuote(chunk.text) + ', ' +
          dollarQuote(metadata) + '::jsonb, ' +
          SQ + embeddingStr + SQ + '::vector(1536), ' +
          lastModifiedSql + ') ON CONFLICT DO NOTHING'
      }
    });
  }
}
return out;

// Preparing Chunks — section-aware chunking with batched embedding output.

const extractedItems = $input.all();

const TOKEN_LIMIT = 350;
const OVERLAP_TOKENS = 75;
const EMBED_BATCH_SIZE = 100;

function toTokens(text) {
  return text.split(/\s+/).filter(Boolean);
}
function toText(tokens) {
  return tokens.join(' ');
}

const allChunks = [];

for (let itemIndex = 0; itemIndex < extractedItems.length; itemIndex++) {
  const extracted = extractedItems[itemIndex]?.json || {};
  const originalFileName = extracted.original_file_name || ('file_' + (itemIndex + 1));
  const title = originalFileName.replace(/\.[^.]+$/, '');
  const fileId = extracted.file_id || '';
  const text = extracted.text || '';
  const lastModified = extracted.last_modified || null;
  if (!text.trim()) continue;

  // Split into sections by ## headings
  const lines = text.split('\n');
  let currentSection = title;
  const sections = [];
  let currentContent = [];

  for (const line of lines) {
    const match = line.match(/^##\s+(.+)$/);
    if (match) {
      if (currentContent.length > 0) {
        sections.push({ heading: currentSection, content: currentContent.join('\n') });
        currentContent = [];
      }
      currentSection = match[1].trim();
    } else {
      currentContent.push(line);
    }
  }
  if (currentContent.length > 0) {
    sections.push({ heading: currentSection, content: currentContent.join('\n') });
  }

  // Chunk each section with overlap
  let chunkIndex = 0;
  for (const section of sections) {
    const sectionText = section.content.trim();
    if (!sectionText) continue;

    const tokens = toTokens(sectionText);
    if (tokens.length === 0) continue;

    let idx = 0;
    while (idx < tokens.length) {
      const take = tokens.slice(idx, idx + TOKEN_LIMIT);
      const chunkText = toText(take);

      // Prefix with doc title and section heading for retrieval context
      const embeddingText = title + ' \u2014 ' + section.heading + '\n\n' + chunkText;

      allChunks.push({
        text: embeddingText,
        section_heading: section.heading,
        chunk_index: chunkIndex,
        original_file_name: originalFileName,
        file_id: fileId,
        last_modified: lastModified,
      });

      chunkIndex++;
      idx += (tokens.length - idx <= TOKEN_LIMIT) ? tokens.length : (TOKEN_LIMIT - OVERLAP_TOKENS);
    }
  }
}

// Deduplicate chunks by content — LLM extraction may produce repeated sections
const seen = new Set();
const uniqueChunks = [];
for (const chunk of allChunks) {
  if (!seen.has(chunk.text)) {
    seen.add(chunk.text);
    uniqueChunks.push(chunk);
  }
}
if (uniqueChunks.length < allChunks.length) {
  console.log('Dedup: removed ' + (allChunks.length - uniqueChunks.length) + ' duplicate chunks out of ' + allChunks.length);
}

// Output as batches for embedding API
const batches = [];
for (let i = 0; i < uniqueChunks.length; i += EMBED_BATCH_SIZE) {
  const batch = uniqueChunks.slice(i, i + EMBED_BATCH_SIZE);
  batches.push({
    json: {
      chunks: batch,
      requestBody: {
        requests: batch.map(c => ({
          model: 'models/gemini-embedding-001',
          content: { parts: [{ text: c.text }] },
          taskType: 'RETRIEVAL_DOCUMENT',
          title: c.original_file_name.replace(/\.[^.]+$/, '') + ' \u2014 ' + c.section_heading,
          outputDimensionality: 1536
        }))
      }
    }
  });
}

return batches;

