// Build Drive Manifest — reconciles the Drive folder against the database.
//
// Emits one SQL statement (as $json.query) that sweeps orphaned rows and
// returns the files still needing (re)processing. One row per live file:
// { file_id, file_name, last_modified }, where last_modified is
// max(createdTime, modifiedTime) as reported by the Drive API.

// Dollar-quoting: SQL-injection-proof escaping for PostgreSQL.
function dollarQuote(s) {
  let tag = 'q';
  while (s.includes('$' + tag + '$')) tag += '_';
  return '$' + tag + '$' + s + '$' + tag + '$';
}

const FOLDER_MIME = 'application/vnd.google-apps.folder';

const files = $input.all()
  .map(i => i.json)
  .filter(f => f && f.id && f.mimeType !== FOLDER_MIME && f.trashed !== true);

// An empty listing is far likelier to be an API or permission failure than a
// genuinely empty folder, and the sweep below would delete every knowledge_base
// row. Refuse rather than wipe the knowledge base.
if (files.length === 0) {
  throw new Error('Drive listing returned 0 usable files for the knowledge base folder. Refusing to run the orphan sweep, which would delete every knowledge_base row. Check the Drive credential, the folder ID, and that "Return All" is enabled.');
}

const manifest = files.map(f => {
  const created = f.createdTime || null;
  const modified = f.modifiedTime || null;
  if (!created && !modified) {
    throw new Error('Drive file "' + (f.name || f.id) + '" returned neither createdTime nor modifiedTime. Set the Google Drive node option Fields to [All] — without it the API omits both timestamps and every file would look changed on every run.');
  }
  const last = (created && modified)
    ? (new Date(modified) > new Date(created) ? modified : created)
    : (modified || created);
  return { file_id: f.id, file_name: f.name || f.id, last_modified: last };
});

// NOT EXISTS rather than NOT IN: NOT IN against a set containing any NULL
// evaluates to NULL and would silently delete nothing.
// IS DISTINCT FROM rather than <>: last_modified is nullable, and <> against
// NULL yields NULL, which would mark a file up-to-date and never reprocess it.
// All CTEs read one snapshot, so the DELETE in `orphans` does not perturb what
// `kb` sees; the work list is still computed against pre-delete state.
const query = [
